const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={running:false,stream:null,events:[],alerts:[
  {level:'high',title:'非开放时段检测到人员活动',desc:'CAM-01 · 北区实验室 · 10:31:44',symbol:'!'},
  {level:'medium',title:'设备功耗短时波动',desc:'SEN-04 · 服务器机房 · 09:56:20',symbol:'ϟ'}
]};
function tick(){const d=new Date();$('#date').textContent=new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',weekday:'short'}).format(d);$('#time').textContent=d.toLocaleTimeString('zh-CN',{hour12:false});}
tick();setInterval(tick,1000);
$$('.nav-item').forEach(b=>b.onclick=()=>{$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.page').forEach(x=>x.classList.remove('active-page'));$('#'+b.dataset.target).classList.add('active-page')});
function toast(msg,danger=false){const t=$('#toast');t.textContent=msg;t.className=danger?'show danger':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',2600)}
function jitter(){if(!state.running)return;const temp=(24.6+(Math.random()-.5)*.8).toFixed(1),hum=Math.round(48+(Math.random()-.5)*4),load=Math.round(35+Math.random()*18),lat=Math.round(20+Math.random()*10);$('#temperature').textContent=temp;$('#humidity').textContent=hum;$('#loadValue').textContent=load;$('#loadBar').style.width=load+'%';$('#latency').textContent=lat;$('#confidence').textContent=(95+Math.random()*3).toFixed(1)+'%';$('#inspectionCount').textContent=128+Math.floor(Math.random()*9);$('#power').textContent=(12.3+Math.random()).toFixed(1)}setInterval(jitter,1600);
$('#demoBtn').onclick=()=>{state.running=!state.running;$('#demoBtn').classList.toggle('running',state.running);$('#demoBtn').innerHTML=state.running?'<span></span>停止自动巡检':'<span></span>开始自动巡检';toast(state.running?'自动巡检已启动，节点开始实时分析':'巡检任务已暂停')};
$$('.segmented button').forEach(b=>b.onclick=async()=>{if(b.dataset.mode==='camera'){try{state.stream=await navigator.mediaDevices.getUserMedia({video:true});$('#camera').srcObject=state.stream;$('#camera').style.display='block';$('#demoScene').style.display='none';$$('.segmented button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast('摄像头已接入，画面仅在本机处理')}catch(e){toast('无法访问摄像头，请检查浏览器权限',true)}}else{if(state.stream)state.stream.getTracks().forEach(t=>t.stop());$('#camera').style.display='none';$('#demoScene').style.display='block';$$('.segmented button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}});
function addEvent(result,danger=true){const row=document.createElement('div');row.className='event-row unread';const time=new Date().toLocaleTimeString('zh-CN',{hour12:false});row.innerHTML=`<span>${time}</span><span>SEN-02</span><span>融合告警</span><span>${result}</span><span><i class="tag ${danger?'danger':'success'}">${danger?'待处理':'正常'}</i></span>`;$('#eventTable .header').after(row)}
$('#simulateAlert').onclick=()=>{$('#smoke').textContent='86';$('#smokeStatus').textContent='异常';$('#smokeStatus').classList.add('danger');$('#fusion').textContent='98%';$('#fusionRing').style.background='conic-gradient(var(--red) 98%,#263849 0)';addEvent('烟雾浓度超过安全阈值');state.alerts.unshift({level:'high',title:'烟雾浓度超过安全阈值',desc:'SEN-02 · 化学实验室 · 刚刚',symbol:'≋'});renderAlerts();$('#alertCount').textContent=state.alerts.length;toast('检测到烟雾异常，已触发本地声光告警',true);setTimeout(()=>{$('#smoke').textContent='18';$('#smokeStatus').textContent='安全';$('#smokeStatus').classList.remove('danger');$('#fusion').textContent='94%';$('#fusionRing').style.background='conic-gradient(var(--green) 94%,#263849 0)'},6000)};
$('#clearEvents').onclick=()=>{$$('#eventTable .unread').forEach(x=>x.remove());toast('已清除已读事件')};
const devices=[['CAM-01','北区实验室','视觉节点','25 ms'],['CAM-03','主实验室','视觉节点','22 ms'],['SEN-01','仪器储藏室','环境节点','18 ms'],['SEN-02','化学实验室','环境节点','19 ms'],['SEN-04','服务器机房','能耗节点','21 ms'],['GATE-01','实验楼入口','门禁节点','16 ms']];
$('#deviceGrid').innerHTML=devices.map((d,i)=>`<article class="device-card"><div class="device-top"><div class="node-icon">${i<2?'◉':i===5?'↳':'⌁'}</div><span class="safe-pill">在线</span></div><h3>${d[0]}</h3><p>${d[1]} · ${d[2]}</p><div class="device-meta"><span>信号 ${92-i*3}%</span><span>延迟 ${d[3]}</span></div></article>`).join('');
function renderAlerts(){$('#alertList').innerHTML=state.alerts.length?state.alerts.map((a,i)=>`<article class="alert-card ${a.level}"><div class="alert-symbol">${a.symbol}</div><div><h3>${a.title}</h3><p>${a.desc}</p></div><button class="resolve-btn" data-alert="${i}">标记已处理</button></article>`).join(''):'<article class="panel" style="text-align:center;color:var(--muted)">当前没有待处理告警</article>';$$('[data-alert]').forEach(b=>b.onclick=()=>{state.alerts.splice(+b.dataset.alert,1);renderAlerts();$('#alertCount').textContent=state.alerts.length;$('#alertHint').textContent=state.alerts.length?'请及时完成处置':'所有告警均已处理';toast('告警已处理并写入处置记录')})}renderAlerts();
